  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://community.abbottlyon.com/us/terms/67f50a6fd2fe3751fd84667f', 'official_site', 'compensation', 'Abbott Lyon''s own Collective terms of service state that advocates who complete the starter challenges receive a $150 product voucher and 15% commission on sales, with points and tiers unlocking bigger rewards as they level up.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.abbottlyon.com/pages/the-collective', 'official_site', 'ugc_collab', 'The brand''s own Collective programme page invites content creators (18+, UK-based, 1K+ followers) to join, promising up to 25% commission as members level up, product vouchers worth over £1,000 in total, personalised follower discounts and chances to be featured on the Abbott Lyon Instagram page.', 'verified', now());
