  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 16, 12, 9, 5, '{"compensation": "The brand''s own terms publish 15% commission on sales at the entry tier, rising to up to 25% at higher tiers per its programme page, plus product vouchers \u2014 strong published cash terms.", "contact_access": "A public programme page with a join route into the brand''s own community platform; no public email was found, so it sits below the top band.", "credibility": "Established UK jewellery brand with a large social following and a long-running, publicly documented creator programme.", "niche_fit": "Personalised jewellery and accessories made for gifting and outfit content \u2014 a core fashion-creator niche with highly visual, demonstrable products.", "opportunity_availability": "Applications are publicly open to UK creators aged 18+ with 1,000+ followers per the programme page.", "ugc_evidence": "A formal, tiered creator community (the Collective, run on Duel) with content challenges, posting requirements, brand reposting rights and Instagram features built into the programme design."}'::jsonb);
