  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.contiki.com/en-au/activity/rep-program', 'official_site', 'ugc_collab', 'Contiki''s own Rep Program page describes a creator-facing sister scheme (run via Commission Factory in AU) with commission tiers of 5%, 7.5% and 10% based on travellers booked, a 90-day cookie, and links/promo codes for social promotion.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 11, 10, 9, 5, '{"compensation": "Published 5% minimum commission on the brand''s own page; on multi-thousand-dollar tour bookings that is a large absolute payout per sale, with higher tiers published for the Rep scheme (to 10%).", "contact_access": "A public affiliate page on contiki.com with a sign-up route and a named dedicated affiliate management team.", "credibility": "Operating since 1962 as part of The Travel Corporation, one of the world''s largest guided-tour groups.", "niche_fit": "Group tours built exclusively for 18-35 travellers \u2014 the exact demographic travel creators reach, with trips that generate weeks of content per booking.", "opportunity_availability": "Free public sign-up for websites and bloggers via the brand''s affiliate page; Rep applications accepted from US, UK, AU, NZ and Canada.", "ugc_evidence": "Contiki runs both a standard affiliate programme and a creator-specific Rep Program with trackable links and promo codes for Instagram, TikTok and YouTube promotion."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Agoda', 'https://www.agoda.com', 'Singapore-based online travel platform in the Booking Holdings group, selling hotel and accommodation bookings (plus flights and activities) across 1.8M+ properties worldwide, with an in-house partner programme and a creator Ambassador scheme.', 'Singapore', 'published') returning id into bid;
