  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Agoda Partners affiliate programme (in-house)', 'https://partners.agoda.com', 'https://partners.agoda.com', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/agoda-affiliate-program/', 'listing', 'affiliate', 'Agoda runs its affiliate programme in-house through Agoda Partners (partners.agoda.com) with tiered commission on departed bookings: 4% for 1-50 monthly departures, 4.5% for 51-300 and 5% for 301+, paid on completed stays.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliatejob.org/blog/best-travel-affiliate-programs-2026', 'listing', 'affiliate', 'A September 2026 check of Agoda''s own partner pages confirms the published tiers (4% below 50 completed bookings a month, 4.5% from 50, 5% from 300) on booking value, run in-house.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://agoda.com/agoda-ambassador', 'official_site', 'ugc_collab', 'Agoda''s own Ambassador page recruits creators with 3,000+ followers on one platform to earn promo-code commission — but its FAQ caps earnings at a maximum of $10 per booking (4% for the first 99 bookings, 5% after), so that creator route is per-booking capped despite ''no limits'' headline language about booking count.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 10, 9, 8, 5, '{"compensation": "Published tiered rates on the Partners programme start at 4% of booking value and rise to 5% (higher via some partner channels); the separate Ambassador code route is capped per booking, which holds this below the top band.", "contact_access": "A public Partner Center sign-up at partners.agoda.com plus a public Ambassador application form on agoda.com.", "credibility": "Booking Holdings subsidiary founded in 2005, with roughly 1.8M+ properties and operations in 28 countries.", "niche_fit": "One of the largest hotel-booking platforms in Asia-Pacific and a Booking Holdings brand \u2014 hotel content is a staple of travel creator output.", "opportunity_availability": "Applications are publicly open but approval-based; the Ambassador scheme requires 3,000+ followers on a single platform.", "ugc_evidence": "Agoda runs a dedicated creator Ambassador scheme (promo codes, campaign features) alongside its publisher programme, though the Ambassador route caps commission at $10 per booking."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Skyscanner', 'https://www.skyscanner.net', 'Edinburgh-founded travel metasearch engine used by 160M+ people a month to compare flights, hotels and car hire across 180 countries, monetising referrals to airlines and OTAs rather than selling travel itself.', 'United Kingdom', 'published') returning id into bid;
