  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://affiliateprogramsguru.com/programs/skyscanner-affiliate-program/.', 'https://www.partners.skyscanner.net/product/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Skyscanner Affiliate Programme (via Impact)', 'https://www.partners.skyscanner.net/product/affiliates', 'https://www.partners.skyscanner.net/product/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/skyscanner-affiliate-program/', 'affiliate_network', 'affiliate', 'Skyscanner''s affiliate programme runs exclusively through Impact and pays a 20% revenue share of the commission Skyscanner itself earns per referred booking (top performers up to 50%), on a 30-day cookie with a $10 minimum payout — the percentage is of Skyscanner''s referral income, not of the booking value.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/skyscanner', 'listing', 'affiliate', 'Referly''s programme summary, drawn from Skyscanner''s own materials, confirms the programme is managed on Impact, pays a flexible performance-based percentage of Skyscanner''s partner commission (no fixed headline rate is published by Skyscanner), and requires 5,000+ monthly unique visitors for website applicants, with social creators directed to a separate Creator Programme.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 13, 8, 6, 5, '{"compensation": "A published 20% base share of Skyscanner''s own referral commission (up to 50% for top performers) \u2014 a high percentage, but of a small per-booking referral fee rather than of booking value, so absolute earnings per booking are modest.", "contact_access": "A public programme page at partners.skyscanner.net with application via Impact and manual review.", "credibility": "One of the world''s largest travel metasearch brands, operating since 2003 and owned by Trip.com Group.", "niche_fit": "The default flight-search brand for travel content; fare comparisons and route finds are highly shareable creator material.", "opportunity_availability": "Eligibility gates apply: websites need 5,000+ monthly unique visitors and HTTPS; social applicants need 1,000+ travel-focused followers.", "ugc_evidence": "Skyscanner steers TikTok/Instagram/YouTube influencers to a separate Creator Programme and runs the affiliate scheme mainly for publishers, so creator-specific evidence is thinner than for product brands."}'::jsonb);
