  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.manitobah.ca/pages/affiliate', 'official_site', 'affiliate', 'Manitobah''s own Affiliate and Creator Program page states commission starts at 6%, with a 60-day cookie, monthly payments to the PayPal address on file in AvantLink/Skimlinks, and expectations aimed at reviewers and social creators with first-hand product experience.', 'verified', now());
