  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 11, 10, 8, 4, '{"compensation": "Published starting rate of 6% on the brand''s own page with a 60-day cookie \u2014 a solid, verifiable base rate for footwear.", "contact_access": "A public programme page on the brand''s own site with a sign-up step and dedicated programme management named as a benefit.", "credibility": "Established Canadian brand (founded 1997) with national retail presence and certified Indigenous ownership, smaller than the global fashion groups in this batch.", "niche_fit": "Distinctive winter footwear with a strong story (Indigenous artistry, cold-weather function) that fits fashion, outdoor and travel-wardrobe content.", "opportunity_availability": "Public application, though the brand states it looks for an established, engaged audience with footwear-review experience.", "ugc_evidence": "The brand''s own page is explicitly an ''Affiliate and Creator Program'' seeking reviewers and social storytellers, with content assets and PR support offered to partners."}'::jsonb);
