  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/mango/', 'affiliate_network', 'affiliate', 'Uppromote''s programme directory states Mango''s US affiliate programme is managed on CJ Affiliate with a 6% base commission, rising to up to 10% for top performers, on a 30-day cookie with monthly payouts.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/417/mango-com-affiliate-program', 'affiliate_network', 'affiliate', 'Sovrn Commerce''s merchant page independently lists Mango.com at 6% commission per sale with a 30-day cookie, corroborating the 6% base rate.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.flexoffers.com/affiliate-programs/mango-us-mx-au-affiliate-program/', 'affiliate_network', 'compensation', 'FlexOffers'' Mango (US/MX/AU) listing shows a much lower 0.8% payout with a 7-day cookie, which conflicts with the 6% published by CJ-directory and Sovrn sources; the 6% figure is recorded as the programme base and the FlexOffers figure treated as a sub-network payout, but the conflict is documented here.', 'needs_review', now());
