  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 8, 8, 8, 8, 3, '{"compensation": "A published rate exists \u2014 3% per the brand''s own recruitment email \u2014 but it is a low percentage, keeping compensation in the lower band.", "contact_access": "A general support email is published on the brand''s own site and the programs are joinable through two networks, but no dedicated affiliate contact was verified.", "credibility": "Large catalogue retailer on two major affiliate networks; a value-positioned marketplace-style store rather than a single established consumer brand.", "niche_fit": "Broad home catalogue (furniture, appliances, d\u00e9cor, outdoor) fits home creators, though the range is generic rather than niche-specific.", "opportunity_availability": "Open affiliate programs on both ShareASale and Awin with public signup routes.", "ugc_evidence": "Affiliate recruitment is public, but no creator-specific or UGC program evidence was found beyond standard affiliate listings."}'::jsonb);
