  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'ZYMOX Affiliate Program (Pet King Brands, via Refersion)', 'https://petkingbrands.refersion.com/affiliate/registration', 'https://petkingbrands.refersion.com/affiliate/registration', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zymox.com/media/7d/c7/ce/1767824142/2025-11-18_PKB_Affiliate.pdf?ts=1767824142', 'official_site', 'affiliate', 'Pet King Brands'' official press release on zymox.com (November 18, 2025) launches the ZYMOX Affiliate Program, accepting applications from content creators, influencers, pet professionals and pet parents via Refersion registration (petkingbrands.refersion.com/affiliate/registration), and publishes affiliateprogram@petkingbrands.com for program questions. No commission rate is stated in the release or on the registration page, so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://zymox.com/media/7d/c7/ce/1767824142/2025-11-18_PKB_Affiliate.pdf?ts=1767824142', 'official_site', 'ugc_collab', 'The release states the program is built around authentic pet content — Reels, TikToks, carousels and UGC-style photos — with accepted affiliates receiving content assets and guidance; it covers the full ZYMOX line plus Oratene for dogs, cats, horses, small animals, exotics, birds and reptiles.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 6, 13, 9, 4, '{"compensation": "No commission rate is published anywhere for the program, so compensation stays low despite the program being official and open.", "contact_access": "A dedicated program email (affiliateprogram@petkingbrands.com) is published in the official launch release alongside an open registration page \u2014 top band.", "credibility": "Established veterinarian-recommended pet health brand from Pet King Brands (Austin, TX) with national product distribution.", "niche_fit": "Pet health care for dogs, cats and horses is a core pets-creator niche, and the program explicitly targets pet content creators.", "opportunity_availability": "Registration is publicly open on Refersion to creators, influencers, pet professionals and pet parents.", "ugc_evidence": "The official launch release describes a program designed around Reels, TikToks, carousels and UGC-style photos, with content assets provided to accepted affiliates."}'::jsonb);
