  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Grove Performance Partnership Program (via Impact)', 'https://www.grove.co/g/partners/', 'https://www.grove.co/g/partners/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.grove.co/g/partners/', 'official_site', 'affiliate', 'Grove Collaborative''s own Partners page (fetched) describes the Grove Performance Partnership Program: partners earn a competitive commission monthly for each checkout converted through their content, tracking runs through a partnerships platform, and the page''s application link goes to Impact (app.impact.com). It targets active content producers in home, beauty, parenting and lifestyle; delivery is US lower-48 only.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.grove.co/g/partners/', 'affiliate_network', 'compensation', 'The official page publishes no rate, and third-party figures conflict — flat $12 per new customer via Impact (LinkClicky), $15 per qualified new customer via CJ (CommissionDex), and percentage figures elsewhere — so commission_rate is null with the conflict documented.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 8, 6, 8, 5, '{"compensation": "A real commission program exists with monthly payouts, but the brand publishes no rate and third-party figures conflict (flat $12 vs $15 per new customer, percentage claims), so the rate is null and compensation scores conservatively.", "contact_access": "The official Partners page carries the application route, but no public partnerships email was verified.", "credibility": "Certified B Corporation and one of the best-known sustainable home retailers in the US.", "niche_fit": "Natural home and cleaning products are a core home-creator niche, and the program explicitly recruits home content producers.", "opportunity_availability": "Applications are open directly from the official Partners page via Impact.", "ugc_evidence": "The program is built around content producers publishing through blogs, newsletters and social channels with brand-provided creative assets."}'::jsonb);
