  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.euhomy.com/pages/ambassador-program', 'official_site', 'affiliate', 'Euhomy''s own Ambassador Program page (fetched) states ambassadors earn sales commission on every sale made through their exclusive discount code, receive a free ice maker from the latest styles every month, and must create unique content and have more than 5,000 followers. No percentage rate is published on the page, so commission_rate is null.', 'verified', now());
