  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 13, 7, 11, 7, 3, '{"compensation": "The brand confirms ambassadors earn commission on every sale plus monthly free product, but publishes no percentage, so compensation scores on structure rather than a verified rate.", "contact_access": "Two published emails on the official program page, including a business inquiries address (market@euhomy.com) \u2014 upper band.", "credibility": "Consumer appliance brand with its own store and marketplace presence; a smaller public track record than the established retailers in this batch.", "niche_fit": "Countertop appliances (ice makers, dehumidifiers, portable fridges) fit home-tech creators and are highly demonstrable on video.", "opportunity_availability": "The ambassador program is publicly open on the brand''s own page but requires more than 5,000 followers.", "ugc_evidence": "The program is explicitly content-based \u2014 ambassadors must provide unique, creative content and promote through their social platforms."}'::jsonb);
